/// Split a request target into `(path, query)` at the FIRST `?`.
///
/// A target with no `?` yields an empty query, never `None`, so a caller
/// never branches on presence. A second `?` stays in the query, where
/// `parse_query` treats it as an ordinary character — dropping it, as a
/// `split('?').nth(1)` decoder does, loses real parameters.
#[must_use]
pub fn split_query(target: &str) -> (&str, &str) {
    match target.split_once('?') {
        Some((path, query)) => (path, query),
        None => (target, ""),
    }
}

/// The path half of a request target, with any query string removed.
///
/// This is the route-matching spelling: `path_only("/api/x?a=1") == "/api/x"`.
#[must_use]
pub fn path_only(target: &str) -> &str {
    split_query(target).0
}

/// Decode a raw query string into its name/value pairs, in order.
///
/// Total: no input errors and no input panics. See the module contract table
/// for every edge. `raw` may carry a leading `?`; it may also be an
/// `application/x-www-form-urlencoded` request body, which has the same
/// grammar.
#[must_use]
pub fn parse_query(raw: &str) -> Vec<(String, String)> {
    pairs(raw)
        .map(|(name, value)| (percent_decode(name), percent_decode(value)))
        .collect()
}

/// The first value for `name` in a raw QUERY STRING, decoded.
///
/// The argument is the query alone — `a=1&b=2`, with or without a leading
/// `?`. Pass a full request target (`/api/spend?payer=0x…`) and this answers
/// `None`, because the first `=` splits the whole thing and the name comes
/// out as `/api/spend?payer`. For a target, use [`target_param`], which is
/// this function after [`split_query`].
///
/// First, not last and not a collapse: every decoder this replaces returned
/// the first match, so conversion is a deletion rather than a migration. Use
/// [`parse_query`] when a repeated name is meaningful.
///
/// This shares [`pairs`] with [`parse_query`], so the two cannot disagree
/// about where a pair begins, and it decodes at most one name and one value —
/// a route-matching hot path must not allocate the whole parameter list to
/// answer one lookup.
#[must_use]
pub fn param(raw: &str, name: &str) -> Option<String> {
    pairs(raw)
        .find(|(candidate, _)| name_is(candidate, name))
        .map(|(_, value)| percent_decode(value))
}

/// The undecoded `(name, value)` slices of a raw query, in order.
///
/// The ONE place the grammar lives: a leading `?` is dropped, empty segments
/// are skipped, and only the first `=` in a segment splits it.
fn pairs(raw: &str) -> impl Iterator<Item = (&str, &str)> {
    let raw = raw.strip_prefix('?').unwrap_or(raw);
    raw.split('&')
        .filter(|segment| !segment.is_empty())
        .map(|segment| match segment.split_once('=') {
            Some((name, value)) => (name, value),
            None => (segment, ""),
        })
}

/// Whether an undecoded parameter name is `name`, decoding only when it must.
///
/// A name carrying no escape is compared as it stands, which is every name in
/// every labs route; the allocation is paid only by the caller who encoded one.
fn name_is(raw_name: &str, name: &str) -> bool {
    if raw_name.bytes().any(|byte| matches!(byte, b'%' | b'+')) {
        percent_decode(raw_name) == name
    } else {
        raw_name == name
    }
}

/// The first value for `name` in a full request target (`path?query`).
///
/// The convenience shape for a handler holding `IngressRequest.path`.
#[must_use]
pub fn target_param(target: &str, name: &str) -> Option<String> {
    param(split_query(target).1, name)
}

/// Percent-decode one query component, resolving `+` to a space.
///
/// Kept private: the module's contract is the pair list, and a second public
/// entry point invites a caller to decode one half of a pair and not the
/// other, which is the divergence being closed.
fn percent_decode(raw: &str) -> String {
    let bytes = raw.as_bytes();
    // The decoded form is never longer than the encoded one.
    let mut out: Vec<u8> = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'%' => {
                let hi = bytes.get(i + 1).and_then(|b| hex_nibble(*b));
                let lo = bytes.get(i + 2).and_then(|b| hex_nibble(*b));
                match (hi, lo) {
                    (Some(hi), Some(lo)) => {
                        out.push(hi * 16 + lo);
                        i += 3;
                    }
                    // A malformed escape is data, not an error: emit the `%`
                    // and carry on from the next byte.
                    _ => {
                        out.push(b'%');
                        i += 1;
                    }
                }
            }
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            byte => {
                out.push(byte);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

/// One hexadecimal digit as its value, or `None` for anything else.
fn hex_nibble(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

