    #[test]
    fn split_query_and_path_only_are_total() {
        assert_eq!(split_query("/api/x?a=1"), ("/api/x", "a=1"));
        assert_eq!(split_query("/api/x"), ("/api/x", ""));
        assert_eq!(split_query("/api/x?"), ("/api/x", ""));
        assert_eq!(split_query(""), ("", ""));
        // A second `?` belongs to the query. A `split('?').nth(1)` decoder
        // drops `b=2` here, losing a real parameter.
        assert_eq!(split_query("/p?a=1?b=2"), ("/p", "a=1?b=2"));
        assert_eq!(path_only("/api/x?a=1"), "/api/x");
        assert_eq!(path_only("/api/x"), "/api/x");
    }

    #[test]
    fn param_reads_the_first_occurrence_and_decodes_it() {
        assert_eq!(param("tag=b&tag=a", "tag").as_deref(), Some("b"));
        assert_eq!(param("a=1&b=2", "missing"), None);
        assert_eq!(param("", "a"), None);
        // Present-and-empty is Some(""), not None.
        assert_eq!(param("a=&b=2", "a").as_deref(), Some(""));
        assert_eq!(param("flag&b=2", "flag").as_deref(), Some(""));
        assert_eq!(param("v=a+b%2Fc%zz", "v").as_deref(), Some("a b/c%zz"));
    }

    #[test]
    fn target_param_reads_a_full_request_target() {
        let target = "/buzz/sub/s1?debug&token=1000.dead&from=2%3A17";
        assert_eq!(target_param(target, "token").as_deref(), Some("1000.dead"));
        // The buzz cursor incident: `URLSearchParams` sends `:` as `%3A`, and
        // the undecoded value made `Cursor::parse` fail, which the caller read
        // as "no cursor" and silently resumed at the wrong offset.
        assert_eq!(target_param(target, "from").as_deref(), Some("2:17"));
        // The buzz valueless-pair incident: `?debug` must not hide `token`.
        assert_eq!(target_param(target, "debug").as_deref(), Some(""));
        assert_eq!(target_param("/buzz/sub/s1", "token"), None);
        assert_eq!(target_param("/p", "a"), None);
    }

    /// The trap the two names invite: a full target handed to `param`.
    ///
    /// It answers `None` rather than the value, and a caller reads that as
    /// "the parameter was not supplied" — so the bug surfaces as a spurious
    /// 400 on a request that was in fact correct.
    #[test]
    fn a_full_target_belongs_to_target_param_not_param() {
        let target = "/api/spend?payer=0xabc";
        assert_eq!(param(target, "payer"), None);
        assert_eq!(target_param(target, "payer").as_deref(), Some("0xabc"));
        // And the query alone works in both, since `target_param` splits
        // a target with no `?` into an empty query rather than refusing.
        assert_eq!(param("payer=0xabc", "payer").as_deref(), Some("0xabc"));
        assert_eq!(param("?payer=0xabc", "payer").as_deref(), Some("0xabc"));
    }

    /// A decoder that panics on a hostile target is a denial of service in a
    /// constrained app, so totality is asserted over the shapes a fuzzer
    /// reaches first rather than only over the curated table.
    #[test]
    fn no_input_shape_panics() {
        let hostile = [
            "%", "%%", "%%%", "%0", "&", "&&", "=", "==", "=a", "&=&", "+", "%2", "a=%C3", "%C3%",
            "\u{0}", "\u{fffd}", "?", "??", "?&?", "a=1&%=%",
        ];
        for raw in hostile {
            let parsed = parse_query(raw);
            // `param` takes the cheap path and `parse_query` the exhaustive
            // one, so this asserts the two entry points cannot disagree.
            for (name, _) in &parsed {
                let first = parsed
                    .iter()
                    .find(|(candidate, _)| candidate == name)
                    .map(|(_, value)| value.clone());
                assert_eq!(param(raw, name), first, "input {raw:?}");
            }
        }
    }

    /// The same agreement over encoded names, where `param` decodes a name
